LUCENE-5239: don't delete same term for the wrong field

git-svn-id: https://svn.apache.org/repos/asf/lucene/dev/trunk@1525851 13f79535-47bb-0310-9956-ffa450edef68

Here is the root cause:
The bug occurs when the system attempts to delete a term from one field that matches a term in another field, leading to incorrect document deletions. This happens because the logic in the `FreqProxTermsWriter` does not properly handle cases where terms for the specified field are not found, allowing for unintended matches and deletions.

Here is the patch:

   private void applyDeletes(SegmentWriteState state, Fields fields) throws IOException {
     // Process any pending Term deletes for this newly
     // flushed segment:
     if (state.segDeletes != null && state.segDeletes.terms.size() > 0) {
       Map<Term,Integer> segDeletes = state.segDeletes.terms;
       List<Term> deleteTerms = new ArrayList<Term>(segDeletes.keySet());
       Collections.sort(deleteTerms);
       String lastField = null;
       TermsEnum termsEnum = null;
       DocsEnum docsEnum = null;
       for(Term deleteTerm : deleteTerms) {
         if (deleteTerm.field().equals(lastField) == false) {
           lastField = deleteTerm.field();
           Terms terms = fields.terms(lastField);
           if (terms != null) {
             termsEnum = terms.iterator(termsEnum);
+          } else {
+            termsEnum = null;
           }
         }

         if (termsEnum != null && termsEnum.seekExact(deleteTerm.bytes())) {
           docsEnum = termsEnum.docs(null, docsEnum, 0);
           int delDocLimit = segDeletes.get(deleteTerm);
           while (true) {
             int doc = docsEnum.nextDoc();
             if (doc == DocsEnum.NO_MORE_DOCS) {
               break;
             }
             if (doc < delDocLimit) {
               if (state.liveDocs == null) {
                 state.liveDocs = state.segmentInfo.getCodec().liveDocsFormat().newLiveDocs(state.segmentInfo.getDocCount());
               }
               if (state.liveDocs.get(doc)) {
                 state.delCountOnFlush++;
                 state.liveDocs.clear(doc);
               }
             } else {
               break;
             }
           }
         }
       }
     }
   }



